    /** Overall success rate as a percentage (0-100) */
    successRate: number;
    /** Average run duration in seconds across all agents in the period */
    averageDurationSeconds: number;
    /** Period start time (ISO 8601, UTC) */
    startTime: string;
    /** Period end time (ISO 8601, UTC) */
    endTime: string;
    /** Per-agent breakdown */
